-- Rolled back by the remote runner. These identities are SQL-only fixtures;
-- separate HTTP tests exercise actual Supabase signature and MFA verification.
select no_plan();
insert into auth.users(id,email,role,aud) values('90000000-0000-4000-8000-000000000001','sql-fixture@demo.invalid','authenticated','authenticated');
insert into auth.sessions(id,user_id,created_at,updated_at) values('90000000-0000-4000-8000-000000000002','90000000-0000-4000-8000-000000000001',clock_timestamp(),clock_timestamp());
insert into app.staff_accounts(user_id,synthetic_key) values('90000000-0000-4000-8000-000000000001','SYN-SQL-FIXTURE');
insert into app.sites(id,name) values('90000000-0000-4000-8000-000000000003','SYN SQL A'),('90000000-0000-4000-8000-000000000004','SYN SQL B');
insert into app.site_memberships(user_id,site_id,role) values('90000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000003','clinician'),('90000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000003','site_admin');
insert into phi.patients(id,site_id,synthetic_identifier,display_name,year_of_birth,is_synthetic) values
('90000000-0000-4000-8000-000000000005','90000000-0000-4000-8000-000000000003','SYN-SQL-A','Synthetic SQL A',1980,true),
('90000000-0000-4000-8000-000000000006','90000000-0000-4000-8000-000000000004','SYN-SQL-B','Synthetic SQL B',1980,true);
select set_config('request.jwt.claims','{"sub":"90000000-0000-4000-8000-000000000001","session_id":"90000000-0000-4000-8000-000000000002","aal":"aal1","role":"authenticated"}',true);
set local role authenticated;
select is(api.begin_staff_session()->>'ok','false','aal1 cannot activate app session');
select is(api.list_patients('90000000-0000-4000-8000-000000000003','direct_care')->>'ok','false','aal1 cannot read patients');
reset role;
select set_config('request.jwt.claims','{"sub":"90000000-0000-4000-8000-000000000001","session_id":"90000000-0000-4000-8000-000000000002","aal":"aal2","role":"authenticated"}',true);
set local role authenticated;
select is(api.begin_staff_session()->>'ok','true','aal2 fresh app session begins');
select is(jsonb_array_length(api.my_memberships()->'data'),2,'both authorised roles are available');
select is(api.list_patients('90000000-0000-4000-8000-000000000003','direct_care')->'data'->0->>'id','90000000-0000-4000-8000-000000000005','own site returns only its patient');
select is(api.list_patients('90000000-0000-4000-8000-000000000004','direct_care')->>'ok','false','other site is refused');
select is(api.get_patient('90000000-0000-4000-8000-000000000003','direct_care','90000000-0000-4000-8000-000000000006')->'error'->>'code','unavailable','foreign patient yields generic denial');
select is(api.get_patient('90000000-0000-4000-8000-000000000003','direct_care','90000000-0000-4000-8000-000000000007')->'error'->>'code','unavailable','missing patient gives same denial');
select is(api.list_patients('90000000-0000-4000-8000-000000000003',null)->>'ok','false','null purpose is refused');
select is(api.list_patients('90000000-0000-4000-8000-000000000003','audit_review')->>'ok','false','wrong purpose is refused');
select is(api.list_site_memberships('90000000-0000-4000-8000-000000000003')->>'ok','true','admin can read memberships');
select is(api.list_audit_events('90000000-0000-4000-8000-000000000003',now()-interval '1 day',clock_timestamp())->>'ok','true','admin audit SELECT works through RLS');
select is(api.list_audit_events('90000000-0000-4000-8000-000000000004',now()-interval '1 day',clock_timestamp())->>'ok','false','admin cannot read other site audit');
select throws_ok('select * from phi.patients','42501',null,'no direct patient read');
select throws_ok('truncate audit.audit_events','42501',null,'authenticated cannot truncate audit');
reset role;
select ok(not exists(select 1 from audit.audit_events where actor_user_id='90000000-0000-4000-8000-000000000001' and outcome='denied_or_not_found' and cardinality(record_ids)>0),'denials disclose no guessed record IDs');
select ok(not exists(select 1 from audit.audit_events where actor_user_id='90000000-0000-4000-8000-000000000001' and site_id='90000000-0000-4000-8000-000000000004'),'denials disclose no foreign site');
select throws_ok('update audit.audit_events set purpose=purpose','P0001','Audit history is append-only','owner accidental update denied');
select throws_ok('delete from audit.operator_events','P0001','Audit history is append-only','operator history deletion denied');
select throws_ok('truncate audit.audit_events','P0001','Audit history is append-only','owner accidental truncate denied');
-- A storage failure must prevent the otherwise allowed patient result.
revoke insert on audit.audit_events from gi_audit_writer;
set local role authenticated;
select throws_ok($$select api.list_patients('90000000-0000-4000-8000-000000000003','direct_care')$$,'42501',null,'audit failure prevents patient response');
reset role;
grant insert on audit.audit_events to gi_audit_writer;
select lives_ok($$insert into phi.patients(site_id,synthetic_identifier,display_name,year_of_birth,is_synthetic) values('90000000-0000-4000-8000-000000000003','VISIT-TEST','Fictional real-mode schema fixture',1980,false)$$,'operator can explicitly create a real-mode record using fictional test data');
update app.site_memberships set active=false where user_id='90000000-0000-4000-8000-000000000001' and role='clinician';
set local role authenticated;
select is(api.list_patients('90000000-0000-4000-8000-000000000003','direct_care')->>'ok','false','site admin alone has no patient access');
reset role;
update app.site_memberships set active=false where user_id='90000000-0000-4000-8000-000000000001';
insert into app.site_memberships(user_id,site_id,role) values('90000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000003','coordinator'),('90000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000004','coordinator');
set local role authenticated;
select is(api.list_patients('90000000-0000-4000-8000-000000000003','intake_support')->>'ok','true','coordinator can support intake');
select is(api.list_audit_events('90000000-0000-4000-8000-000000000003',now()-interval '1 day',clock_timestamp())->>'ok','false','coordinator cannot read audit history');
select is(api.list_patients('90000000-0000-4000-8000-000000000004','intake_support')->'data'->0->>'id','90000000-0000-4000-8000-000000000006','explicit second-site membership gives only that site records');
reset role;
update app.site_memberships set active=false where user_id='90000000-0000-4000-8000-000000000001';
set local role authenticated;
select is(jsonb_array_length(api.my_memberships()->'data'),0,'no membership gives an empty own-site list');
select is(api.list_patients('90000000-0000-4000-8000-000000000003','direct_care')->>'ok','false','membership removal is effective without JWT refresh');
reset role;
update app.site_memberships set active=true where user_id='90000000-0000-4000-8000-000000000001' and role in('clinician','site_admin');
update app.staff_sessions set last_activity_at=clock_timestamp()-interval '2 hours' where user_id='90000000-0000-4000-8000-000000000001';
set local role authenticated;
select is(api.touch_staff_session()->>'ok','false','late touch cannot resurrect');
select is(api.begin_staff_session()->>'ok','false','late begin cannot resurrect');
select is(api.list_patients('90000000-0000-4000-8000-000000000003','direct_care')->>'ok','false','expired session blocks signed JWT');
reset role;
update app.staff_sessions set last_activity_at=clock_timestamp(),expires_at=clock_timestamp()-interval '1 second' where user_id='90000000-0000-4000-8000-000000000001';
set local role authenticated;
select is(api.touch_staff_session()->>'ok','false','absolute expiry cannot be renewed');
reset role;
update app.staff_sessions set expires_at=clock_timestamp()+interval '1 hour' where user_id='90000000-0000-4000-8000-000000000001';
set local role authenticated;
select is(api.end_staff_session()->>'ok','true','explicit signout commits revocation');
select is(api.begin_staff_session()->>'ok','false','revoked session cannot be reactivated');
select is(api.session_status()->>'ok','false','old JWT denied after signout');
reset role;
select * from finish();
